CREATE FUNCTION assert_true(boolean,text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF $1 IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',$2; END IF; RAISE NOTICE 'PASS: %',$2; END $$;
CREATE FUNCTION refuses(text,text) RETURNS boolean LANGUAGE plpgsql AS $$ BEGIN EXECUTE $1; RETURN false; EXCEPTION WHEN OTHERS THEN RETURN SQLSTATE=$2; END $$;
INSERT INTO agents VALUES ('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001',100.23,false),('00000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000002',0,false);
INSERT INTO staff VALUES('30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001');
SELECT set_config('test.uid','30000000-0000-0000-0000-000000000001',false);
SET ROLE authenticated;
SELECT assert_true(refuses($$SELECT fn_generate_credit_invoice('00000000-0000-0000-0000-000000000002','2026-09-01','2026-09-08',1,'2026-09-10')$$,'42501'),'staff cannot invoice another club');
SELECT assert_true(refuses($$SELECT fn_generate_all_credit_invoices('2026-09-08')$$,'42501'),'browser cannot run global invoicing');
SELECT assert_true((fn_generate_credit_invoice('00000000-0000-0000-0000-000000000001','2026-09-01','2026-09-08',60.23,'2026-09-10')->>'success')::boolean,'own club staff resolves agents primary key');
SELECT set_config('test.uid','10000000-0000-0000-0000-000000000001',false);
SELECT assert_true((fn_generate_credit_invoice('00000000-0000-0000-0000-000000000001','2026-09-01','2026-09-08',60.23,'2026-09-10')->>'duplicate')::boolean,'agent user id resolves own invoice and replay');
SELECT assert_true(NOT(fn_generate_credit_invoice('00000000-0000-0000-0000-000000000001','2026-09-02','2026-09-09',100.23,'2026-09-11')->>'success')::boolean,'unpaid debt cannot be billed twice');
SELECT assert_true((fn_generate_credit_invoice('00000000-0000-0000-0000-000000000001','2026-09-02','2026-09-09',40,'2026-09-11')->>'success')::boolean,'only remaining uninvoiced debt is billed');
DO $$ DECLARE value text; BEGIN FOREACH value IN ARRAY ARRAY['NaN','Infinity','-Infinity','0','-1','0.001'] LOOP PERFORM assert_true(refuses(format('SELECT fn_generate_credit_invoice(%L,%L,%L,%L::numeric,%L)','00000000-0000-0000-0000-000000000001','2026-09-01','2026-09-08',value,'2026-09-10'),'22023'),'invalid amount '||value); END LOOP; END $$;
SELECT assert_true(refuses($$SELECT fn_generate_credit_invoice('00000000-0000-0000-0000-000000000001','2026-09-10','2026-09-08',1,'2026-09-10')$$,'22023'),'reversed dates rejected');
SELECT assert_true(refuses($$SELECT fn_generate_credit_invoice('00000000-0000-0000-0000-000000000001','2026-09-01','infinity',1,'infinity')$$,'22023'),'unbounded dates rejected');
RESET ROLE;
SELECT assert_true((SELECT sum(amount_remaining)=100.23 AND count(*)=2 FROM credit_invoices),'all invoices sum to drawn credit');
SELECT set_config('test.engine','true',false);
SET ROLE service_role;
SELECT assert_true((fn_generate_all_credit_invoices('2026-09-10')->>'generated')::int=0,'weekly close does not reissue old debt');
RESET ROLE;
UPDATE agents SET credit_used=credit_used+1.17 WHERE id='00000000-0000-0000-0000-000000000001';
SET ROLE service_role;
SELECT assert_true((fn_generate_all_credit_invoices('2026-09-10')->>'generated')::int=1,'newly drawn debt is invoiced');
SELECT assert_true((fn_generate_all_credit_invoices('2026-09-10')->>'duplicate')::int=1,'weekly retry is duplicate');
RESET ROLE;
SELECT assert_true((SELECT sum(amount_remaining)=101.40 FROM credit_invoices),'whole-cent obligation conservation');
-- A later agent failure rolls back the earlier invoice in the same bulk attempt.
UPDATE agents SET credit_used=credit_used+1 WHERE id='00000000-0000-0000-0000-000000000001';
UPDATE agents SET credit_used='NaN' WHERE id='00000000-0000-0000-0000-000000000002';
SET ROLE service_role;
SELECT assert_true(refuses($$SELECT fn_generate_all_credit_invoices('2026-09-11')$$,'23514'),'invalid later agent aborts batch');
RESET ROLE;
SELECT assert_true((SELECT count(*)=3 FROM credit_invoices),'failed batch leaves no earlier invoice');
SELECT assert_true(NOT has_function_privilege('anon','fn_generate_credit_invoice(uuid,timestamptz,timestamptz,numeric,timestamptz)','EXECUTE'),'anonymous generation denied');
